ALTER TABLE sophonz_logs.logs_v2 ON CLUSTER '{{.SOPHONZ_CLUSTER}}' ADD COLUMN IF NOT EXISTS sessionSdkV1 LowCardinality(String) MATERIALIZED multiIf(upper(ClientPlatform) = 'WEB', 'web', lower(ResourceAttributes['telemetry.sdk.language']) = 'webjs' OR ResourceAttributes['telemetry.sdk.name'] = '@sophonz/browser-sdk', 'web', lower(ClientPlatform) IN ('ios','android'), lower(ClientPlatform), lower(ResourceAttributes['os.name']) IN ('ios','ipados'), 'ios', lower(ResourceAttributes['os.name']) = 'android','android','');
ALTER TABLE sophonz_logs.distributed_logs_v2 ON CLUSTER '{{.SOPHONZ_CLUSTER}}' ADD COLUMN IF NOT EXISTS sessionSdkV1 LowCardinality(String) MATERIALIZED multiIf(upper(ClientPlatform) = 'WEB', 'web', lower(ResourceAttributes['telemetry.sdk.language']) = 'webjs' OR ResourceAttributes['telemetry.sdk.name'] = '@sophonz/browser-sdk', 'web', lower(ClientPlatform) IN ('ios','android'), lower(ClientPlatform), lower(ResourceAttributes['os.name']) IN ('ios','ipados'), 'ios', lower(ResourceAttributes['os.name']) = 'android','android','');
ALTER TABLE sophonz_logs.logs_v2 ON CLUSTER '{{.SOPHONZ_CLUSTER}}' ADD PROJECTION IF NOT EXISTS session_by_sdk_minute_v1 (SELECT ServiceNamespace, TenantID, sessionSdkV1, sessionMinuteV1, ServiceName, tupleElement(sessionFactsV1, 'sid'), min(toUnixTimestamp64Milli(Timestamp)), max(toFloat64(toUnixTimestamp64Milli(Timestamp))), maxIf(tuple(toUnixTimestamp64Nano(Timestamp), tupleElement(sessionFactsV1, 'eventKey'), toString(tupleElement(sessionFactsV1, 'device'))), notEmpty(tupleElement(sessionFactsV1, 'device'))), maxIf(tuple(toUnixTimestamp64Nano(Timestamp), tupleElement(sessionFactsV1, 'eventKey'), toString(tupleElement(sessionFactsV1, 'version'))), notEmpty(tupleElement(sessionFactsV1, 'version'))), maxIf(tuple(toUnixTimestamp64Nano(Timestamp), tupleElement(sessionFactsV1, 'eventKey'), toString(tupleElement(sessionFactsV1, 'person'))), notEmpty(tupleElement(sessionFactsV1, 'person'))), maxIf(tuple(toUnixTimestamp64Nano(Timestamp), tupleElement(sessionFactsV1, 'eventKey'), toString(tupleElement(sessionFactsV1, 'installation'))), notEmpty(tupleElement(sessionFactsV1, 'installation'))), sum(toUInt64(tupleElement(sessionFactsV1, 'navigation'))), sum(toUInt64(notEmpty(tupleElement(sessionFactsV1, 'route')))), sum(toUInt64(tupleElement(sessionFactsV1, 'request'))), sum(toUInt64(tupleElement(sessionFactsV1, 'failed'))), groupArrayIf(tuple(toUnixTimestamp64Nano(Timestamp), tupleElement(sessionFactsV1, 'eventKey'), tupleElement(sessionFactsV1, 'route')), notEmpty(tupleElement(sessionFactsV1, 'route'))) GROUP BY ServiceNamespace, TenantID, sessionSdkV1, sessionMinuteV1, ServiceName, tupleElement(sessionFactsV1, 'sid'));
